```typescript
import { Component, Output, EventEmitter } from '@angular/core';
import { Subject } from 'rxjs';

@Component({
  selector: 'app-data-display',
  template: ''
})
export class DataDisplayComponent {
  @Output() dataChange = new EventEmitter();
