  private templateRef = inject(TemplateRef);
  private viewContainerRef = inject(ViewContainerRef);

  selectFrom = input.required<DataSource<unknown>>();

  async ngOnInit() {
    const data = await this.selectFrom().load();
    this.viewContainerRef.createEmbeddedView(this.templateRef, {
      $implicit: data,
    });
  }
}
```

In the template, use `<ng-template [select]="dataSource">` where `dataSource` implements your DataSource interface. The directive will render the ng-template content with the loaded data available as `$implicit`.

You can combine both guards by providing them together in your directive's providers array. Here's the complete pattern:

```typescript
import { Directive, Input } from '@angular/core';

@Directive({
  selector: '[myComprehensiveDirective]',
  providers: [
    {
      provide: ngTemplateContextGuard,
      useFactory: myComprehensiveDirectiveNgTemplateContextGuard,
      deps: [MyComprehensiveDirective]
    },
    {
      provide: ngTemplateGuard_(input),
      useFactory: myComprehensiveDirectiveNgTemplateGuard,
      deps: [MyComprehensiveDirective]
    }
  ]
})
class MyComprehensiveDirective {
  @Input() mode: 'edit' | 'view';
  @Input() data: any;
}

function myComprehensiveDirectiveNgTemplateContextGuard(
  directive: MyComprehensiveDirective
): any {
  return {
    editMode: directive.mode === 'edit',
    viewMode: directive.mode === 'view'
  };
}

function myComprehensiveDirectiveNgTemplateGuard(
  directive: MyComprehensiveDirective
): any {
  return {
    canEdit: directive.mode === 'edit',
    canView: directive.mode === 'view'
  };
}
```

This configuration ensures both the template context object and input expression narrowing are validated at compile time, providing maximum type safety for your custom directives.

To narrow the input expression by defining a type assertion function, implement the static `ngTemplateGuard_*` method on your directive class. This tells the template type-checker to assert the expression bound to the input.

```ts
@Directive(...)
class ActorIsUser {
  actor = input<User | Robot>();

  static ngTemplateGuard_actor(dir: ActorIsUser, expr: User | Robot): expr is User {
    return true;
  }
}
```

Type-checking will behave within the template as if the `ngTemplateGuard_actor` has been asserted on the expression bound to the input.

For directives that only render their templates when an input is truthy, use a literal type of `'binding'` on the `ngTemplateGuard_*` property. This signals to the template type-checker that the binding expression itself should be used as the guard.

```ts
@Directive(...)
class CustomIf {
  condition = input.required<boolean>();

  static ngTemplateGuard_condition: 'binding';
}
```

The template type-checker will behave as if the expression bound to `condition` was asserted to be truthy within the template.

The return statement is included to prevent TypeScript errors during the directive definition phase. While the logic inside the guard does not affect runtime behavior (since the template already knows the narrowed type), omitting the return would cause a compilation error because the function signature requires a boolean return value.

```ts
static ngTemplateGuard_actor(dir: ActorIsUser, expr: User | Robot): expr is User {
  return true;
}
```

This ensures the directive definition remains valid while allowing the template to utilize the narrowed type safely.

To properly type the context within a generic structural directive, you must implement a static `ngTemplateContextGuard` function. This acts as a compile-time type assertion that links the directive's generic type to the template context interface.

```ts
@Directive(...)
export class SelectDirective<T> {
  // Define the guard to narrow context types
  static ngTemplateContextGuard<T>(
    dir: SelectDirective<T>,
    ctx: any
  ): ctx is SelectTemplateContext<T> {
    return true;
  }

  selectFrom = input.required<DataSource<T>>();
}
```

This guard ensures TypeScript recognizes the context type without runtime overhead.

The interface should map the directive's generic parameter to the context properties. For a directive using `SelectTemplateContext<T>`, define an interface with `$implicit` matching type `T`.

```ts
export interface SelectTemplateContext<T> {
  $implicit: T;
}
```

This ensures TypeScript correctly infers types when accessing data inside the template.

You can use the `hostDirectives` property to define an array of directives to apply to the host. Here is the pattern:

```typescript
export class MyComponent {
  hostDirectives = [
    Directive1,
    Directive2
  ];
}
```

You can apply directives to a component by adding a `hostDirectives` property to your component decorator. This creates what Angular calls _host directives_. When the framework renders your component, Angular automatically creates an instance of each host directive and applies its host bindings to the component's host element.

```typescript
import { Component } from '@angular/core';
import { MenuBehavior } from './menu-behavior.directive';

@Component({
  selector: 'admin-menu',
  templateUrl: './admin-menu.html',
  hostDirectives: [MenuBehavior],
})
export class AdminMenu {}
```

This works identically to applying `MenuBehavior` directly to the `<admin-menu>` element in your template, but keeps the directive definition separate from view logic.

Angular applies host directives statically at compile time with several important constraints:

1. **No runtime addition**: You cannot dynamically add directives at runtime through `hostDirectives`
2. **Standalone flag restriction**: Directives used in `hostDirectives` may not specify `standalone: false`
3. **Selector ignored**: Angular ignores the `selector` property of directives applied in `hostDirectives`
4. **API exposure**: By default, host directive inputs and outputs are not exposed as part of the component's public API

```typescript
// This will cause a compile error - standalone must be true
@Component({
  hostDirectives: [SomeDirective],
})
export class MyComponent {}

// Correct usage with standalone directive
import { SomeDirective } from './some.directive';

@Component({
  hostDirectives: [SomeDirective],
})
export class MyComponent {}
```

For exposing inputs/outputs, you need to use the `includingInputsAndOutputs` configuration as documented in the framework architecture.

By default, Angular excludes inputs and outputs from host directives to prevent unintended API exposure. To explicitly include them, you must expand the directive entry within the hostDirectives array using the inputs and outputs properties. Here is the configuration:

```typescript
@Component({
  selector: 'admin-menu',
  templateUrl: './admin-menu.html',
  hostDirectives: [
    {
      directive: MenuBehavior,
      inputs: ['menuId'],
      outputs: ['menuClosed'],
    },
  ],
})
export class AdminMenu {}
```

Consumers can then bind these attributes in their templates.

You can alias inputs and outputs to customize your component's public API by using a colon separator in the configuration. This allows you to bind using a different name than the original directive property:

```typescript
@Component({
  selector: 'admin-menu',
  templateUrl: './admin-menu.html',
  hostDirectives: [
    {
      directive: MenuBehavior,
      inputs: ['menuId: id'],
      outputs: ['menuClosed: closed'],
    },
  ],
})
export class AdminMenu {}
```

The template binding will then use the aliased name:

You can use the `hostDirectives` property on your directive definition. This enables transitive aggregation of multiple behaviors where all host bindings apply to the host element. Here is the code pattern:
```ts
@Directive({
  hostDirectives: [ExistingDirective1, ExistingDirective2],
})
export class ComposedDirective {}
```

Yes, you can apply already-composed behaviors from one directive to another directive. Each level's host bindings will apply to the outermost host element. Example:
```ts
@Directive({
  hostDirectives: [ComposedDirective],
})
export class SpecializedDirective {}
```

Yes, components with `hostDirectives` can override any host bindings specified by a host directive because the target component applies its own host bindings last in the execution sequence.

```typescript
@Component({
  selector: 'admin-menu',
  host: {
    '[class.active]': '!isDisabled', // Overrides directive binding
  },
  hostDirectives: [MenuBehavior],
})
export class AdminMenu {}
```

Since the component's bindings are applied after the host directive's bindings, they take precedence in the DOM.

The order of operations extends to nested chains of host directives recursively. Innermost directives instantiate and run lifecycle hooks first, followed by outer layers.

```typescript
@Directive({})
export class Tooltip {}

@Directive({
  hostDirectives: [Tooltip],
})
export class CustomTooltip {}

@Directive({
  hostDirectives: [CustomTooltip],
})
export class EvenMoreCustomTooltip {}
```

Execution sequence:
1. `Tooltip` instantiated
2. `CustomTooltip` instantiated
3. `EvenMoreCustomTooltip` instantiated
4. Innermost directive receives inputs (`ngOnInit`)
5. Outer directives receive inputs (`ngOnInit`)
6. Innermost directive applies host bindings
7. Outer directives apply host bindings

By specifying `hostDirectives` on the component or directive metadata, you enable bidirectional dependency injection. This allows the component to inject instances of those host directives and vice versa.

```typescript
@Component({
  selector: 'app-child',
  hostDirectives: [HostDirective]
})
export class ChildComponent {
  constructor(@Inject(HostDirective) private hostRef: HostDirective) {}
}
```

This pattern ensures the component can utilize functionality defined in the host directives directly within its constructor or methods.

When applying host directives to a component, both the component and host directives can define providers. However, if they both provide the same injection token, the providers defined by the class with `hostDirectives` take precedence over providers defined by the host directives themselves.

```typescript
@Component({
  selector: 'app-child',
  hostDirectives: [HostDirective],
  providers: [
    { provide: MyToken, useValue: 'component-provider' }
  ]
})
export class ChildComponent {}

@Directive({
  selector: '[host-directive]',
  providers: [
    { provide: MyToken, useValue: 'directive-provider' }
  ]
})
export class HostDirective {}
```

In this scenario, `MyToken` will resolve to `'component-provider'`, as the component's provider overrides the host directive's definition.

Yes, you can define providers in both locations when applying host directives to a component. However, you must be aware of the precedence hierarchy to avoid unexpected token resolution.

```typescript
@Component({
  selector: 'app-child',
  hostDirectives: [HostDirective],
  providers: [
    { provide: GlobalService, useValue: new GlobalService() }
  ]
})
export class ChildComponent {}

@Directive({
  selector: '[host-directive]',
  providers: [
    { provide: LocalConfig, useValue: 'local' }
  ]
})
export class HostDirective {}
```

Both `GlobalService` and `LocalConfig` will be available in the injection context. If you attempt to provide the same token (e.g., `GlobalService`) in both places, the component's provider definition wins.

When a directive appears both through a template selector AND as a host directive, Angular keeps only the template match and discards all host directive matches. This is because a template match represents the full directive with its complete public API, while a host directive match represents Partial<YourDirective> where only explicitly listed inputs and outputs are exposed.

```ts
@Directive({selector: '[hoverable]'})
export class Hoverable {}

@Component({
  selector: 'app-button',
  hostDirectives: [Hoverable],
})
export class Button {}
```

```html
<!-- Angular keeps only the selector match, which has the full public API. -->
<app-button hoverable></app-button>
```

The mental model is that template selectors provide complete directive functionality while host directives are partial applications.

This error occurs when Angular merges duplicate host directive matches but finds that two instances expose the same input or output under different aliases. During merging, Angular combines all input/output mappings from all instances, and conflicting aliases trigger NG8024.

```ts
@Directive({
  selector: '[popoverTrigger]',
  hostDirectives: [{directive: TriggerRef, inputs: ['triggerId: popoverTriggerId']}],
})
export class PopoverTrigger {}

@Directive({
  selector: '[dropdownTrigger]',
  hostDirectives: [
    {directive: TriggerRef, inputs: ['triggerId: dropdownTriggerId']}, // different alias!
  ],
})
export class DropdownTrigger {}
```

```html
<!-- Error: triggerId is exposed as both "popoverTriggerId" and "dropdownTriggerId". -->
<button popoverTrigger dropdownTrigger></button>
```

To resolve this, ensure both paths expose the shared input or output under the same alias, or do not expose it at all.

```ts
@Directive({
  selector: '[popoverTrigger]',
  hostDirectives: [{directive: TriggerRef, inputs: ['triggerId: triggerId']}],
})
export class PopoverTrigger {}

@Directive({
  selector: '[dropdownTrigger]',
  hostDirectives: [
    {directive: TriggerRef, inputs: ['triggerId: triggerId']}, // same alias
  ],
})
export class DropdownTrigger {}
```

Angular automatically merges all instances of the same directive into a single directive instance when it appears multiple times as a host directive. The input and output mappings from all instances are combined, resolving the classic diamond inheritance problem.

```ts
@Directive({
  host: {
    '[attr.data-trigger-id]': 'triggerId',
  },
})
export class TriggerRef {
  readonly triggerId = `trigger-${crypto.randomUUID()}`;
}

@Directive({
  selector: '[popoverTrigger]',
  hostDirectives: [TriggerRef],
})
export class PopoverTrigger {
  readonly triggerRef = inject(TriggerRef);
}

@Directive({
  selector: '[dropdownTrigger]',
  hostDirectives: [TriggerRef],
})
export class DropdownTrigger {
  readonly triggerRef = inject(TriggerRef);
}
```

```html
<!-- Angular keeps one TriggerRef instance, shared by both triggers. -->
<button popoverTrigger dropdownTrigger>Actions</button>
```

Because Angular produces only one instance of the shared directive, both PopoverTrigger and DropdownTrigger receive the same TriggerRef instance when they inject it.

