Key differences:
- Regular `signal`: Passes a default value directly, no automatic updates
- `linkedSignal`: Passes a computation function that re-evaluates when linked state changes

Example implementation:
```typescript
@Component({
  selector: 'app-shipping-picker',
  template: `{{ selectedOption() }}`
})
export class ShippingMethodPicker {
  shippingOptions: Signal<ShippingMethod[]> = getShippingOptions();

  // Use linkedSignal for automatic invalidation protection
  selectedOption = linkedSignal(() => this.shippingOptions()[0]);

  changeShipping(index: number) {
    this.selectedOption.set(this.shippingOptions()[index]);
  }
}
```

