  <input type="email" name="email" [(ngModel)]="formData.email" required email>
</form>

The onSubmit method receives the form object as a parameter:

onSubmit(form: NgForm) {
  if (form.valid) {
    // Process valid form data
    console.log('Valid:', form.value);
