To validate required email input in a template-driven form, bind the model using [(ngModel)] and attach Validators.required. Display the error conditionally based on whether the control is touched or dirty.

```typescript
// component.ts
import { Component } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';

@Component({
  selector: 'app-email-form',
  templateUrl: './email-form.component.html'
})
export class EmailFormComponent {
