```

```html
<!-- email-form.component.html -->
<input 
  type="email" 
  [(ngModel)]="email" 
  name="email"
  #emailControl="ngModel"
  required>

<div *ngIf="emailControl.errors?.required && (emailControl.touched || emailControl.dirty)">
