import { Directive, Input, OnInit } from '@angular/core';
import { NG_ASYNC_VALIDATORS, AsyncValidatorFn } from '@angular/forms';
import { UniqueRoleValidator } from './unique-role.validator';

@Directive({
  selector: '[appUniqueUnambiguousRole]',
  providers: [
    {
      provide: NG_ASYNC_VALIDATORS,
      useExisting: Directive
    }
  ]
})
export class RoleDirective implements OnInit {
  @Input() appUniqueUnambiguousRole!: string;

  ngOnInit(): void {
    const validatorFn: AsyncValidatorFn = (control) => {
      if (!this.appUniqueUnambiguousRole) return null;
      return new UniqueRoleValidator(this.appUniqueUnambiguousRole).validate(control.value);
    };
  }
}

