import { AbstractControl } from '@angular/forms';

export class UniqueRoleValidator {
  constructor(private rolePrefix: string) {}

  async validate(control: AbstractControl): Promise<boolean> {
    const value = control.value;
    if (!value || value === this.rolePrefix) return true;

    // Fetch from API to check uniqueness
    const response = await fetch(`/api/roles/check/${value}`);
    return response.ok;
  }
}

