Directly referencing browser-specific globals like `document` will cause errors during server-side rendering because these objects do not exist in the Node.js environment. Instead, use the [`DOCUMENT`](api/core/DOCUMENT) token to access the document object in a platform-agnostic way. This ensures your application runs consistently across both client and server platforms.

```ts
import {inject, DOCUMENT, Service} from '@angular/core';

@Service()
export class CanonicalLinkService {
  private readonly document = inject(DOCUMENT);

  setCanonical(href: string): void {
    const link = this.document.createElement('link');
    link.rel = 'canonical';
    link.href = href;
    this.document.head.appendChild(link);
  }
}
```

You must import `DOCUMENT` from `@angular/core`. Combine this with the `inject` function to retrieve the instance within your class field initializer.

```ts
import {inject, DOCUMENT} from '@angular/core';

