});
```

Configure the coverageThreshold property in your karma.config.ts file to specify required percentages for statements, branches, functions, and lines.

```typescript
export function config(karma: KarmaConfig) {
  karma.set({
    frameworks: ['jasmine', 'karma-jasmine-html-reporter'],
    reporters: ['progress', 'coverage'],
    coverageReporter: {
      dir: 'coverage',
      subdir: '.',
