Use a cooldown mechanism or state guard to prevent animation stacking:

increment-decrement.ts:
```typescript
import { Component, OnInit } from '@angular/core';

@Component({
  selector: 'app-native-css',
  templateUrl: './increment-decrement.html',
  styleUrls: ['./increment-decrement.css']
})
export class NativeCssComponent implements OnInit {
  count = 0;
  animationDuration = 300;
  isAnimating = false;

  ngOnInit() {
    // Initialize with a fresh state
    this.isAnimating = false;
  }

  increment() {
    if (this.isAnimating) return;

    this.count++;
    this.isAnimating = true;
    const el = document.querySelector('.counter');
    if (el) {
      el.classList.add('increment');
      setTimeout(() => {
        el.classList.remove('increment');
        this.isAnimating = false;
      }, this.animationDuration);
    }
  }

  decrement() {
    if (this.isAnimating) return;

    this.count--;
    this.isAnimating = true;
    const el = document.querySelector('.counter');
    if (el) {
      el.classList.add('decrement');
      setTimeout(() => {
        el.classList.remove('decrement');
        this.isAnimating = false;
      }, this.animationDuration);
    }
  }
}
```

**Alternative: CSS-only approach using animation states:**
