To handle transition end events safely, ensure listeners are removed during component destruction. Additionally, verify that the transition actually occurred on the intended element by checking transitioned properties. Here is a robust implementation:

```typescript
import { Component, OnDestroy, ViewChild, ElementRef } from '@angular/core';

@Component({
  selector: 'app-parent',
  template: '<div #box>Box</div>'
})
export class ParentComponent implements OnDestroy {
  @ViewChild('box') boxRef: ElementRef;
  private transitionEndListener: (event: TransitionEvent) => void;

  constructor() {}

  startTransition() {
    if (this.boxRef?.nativeElement) {
      this.transitionEndListener = (event: TransitionEvent) => {
        // Verify the transitioned property to ensure correctness
        const computedStyle = window.getComputedStyle(this.boxRef.nativeElement);
        if (computedStyle.getPropertyValue('opacity') !== '1') {
          console.log('Transition completed');
        }
      };
      this.boxRef.nativeElement.addEventListener('transitionend', this.transitionEndListener);
    }
  }

  ngOnDestroy() {
    // Critical: Remove listener to prevent memory leaks
    if (this.boxRef?.nativeElement) {
      this.boxRef.nativeElement.removeEventListener('transitionend', this.transitionEndListener);
    }
  }
}
```

This pattern ensures cleanup and prevents duplicate triggers from bubbling up incorrectly.

