Use `provideCheckNoChangesConfig` with the exhaustive flag enabled to periodically verify no bindings updated without notification. Here is the implementation:

```typescript
import { provideCheckNoChangesConfig } from '@angular/core';
import { ApplicationConfig } from '@angular/core';

const appConfig: ApplicationConfig = {
  providers: [
    provideCheckNoChangesConfig({
      exhaustive: true,
      interval: 1000
    })
